public interface Remunerator {
    double deductFoodFee(); // abstract

    default double deductHealthInsurancePremium() {
        return 0.05; // Default implementation
    }
}

public class PartTimeEmployee implements Remunerator {
    public double deductFoodFee() {
        return 500;
    }
    // Not overriding deductHealthInsurancePremium() – default used
}

interface Greeting {
    default void hello() { System.out.println("hello from A"); }
}

interface GreetingExtn extends Greeting {
    default void hello() { System.out.println("hello from B"); }
}

public class InheritanceProblem implements Greeting, GreetingExtn {
    public static void main(String[] args) {
        new InheritanceProblem().hello();  // Outputs: hello from B
    }
}

public interface Remunerator {
    static double deductForPension(double salary) {
        return salary * 0.05;
    }
}

// Usage
double newSalary = Remunerator.deductForPension(oldSalary);

public class EmployeeComparator implements Comparator<Employee> {
    public int compare(Employee e1, Employee e2) {
        return e1.getEmpNo().compareTo(e2.getEmpNo());
    }
}

